float3 hsv(float h, float s, float v)
{
    float3 c = frac(h + float3(0.0, 2.0 / 3.0, 1.0 / 3.0));
    return ((saturate(abs(c * 6.0 - 3.0) - 1.0) - 1.0) * s + 1.0) * v;
}

float rand2(float2 p)
{
    return frac(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}

float3 getPattern(float2 uv, float t)
{
    float hash = ceil( _Beat.y);
    float it = floor(t);

    float2 p = uv;
    float2 id = float2(0.0, 0.0);
    float3 col = float3(0.0, 0.0, 0.0);

    for (float i = 0.0; i < 12.0; i += 1.0)
    {
        p = p * 2.0;
        float2 grid = floor(p);
        id = id * 2.0 + grid;
        p = frac(p);
        float rand = rand2(id + hash.xx);
        col = rand < 0.25 ? _AccentColor1 : rand < 0.5 ? _AccentColor2 : rand < 0.75 ? _SubAccentColor1 : _SubAccentColor2; 

        float absDepth = i + it;

        bool isCenter = abs(id.x + 0.5) < 1.0 && abs(id.y + 0.5) < 1.0;
        if (!isCenter && rand2(id + absDepth * 0.1) < 0.4)
        {
            break;
        }
    }

    float border = step(0.05, p.x) * step(0.05, p.y) * step(p.x, 0.95) * step(p.y, 0.95);
    return col * border;
}

float4 Frag(VsOutput input) : SV_TARGET
{
    float2 resolution = _Resolution.xy;

    float2 originalUv = input.uv.xy;
    float2 uv = (originalUv * 2.0 - 1.0) * resolution / max(resolution.x, resolution.y);
    float r = length(uv);

    float t = _Time.x * _UserFloat.x;
    float ft = frac(t);

    float zoom = exp2(-ft);
    float2 zoomedUV = uv * zoom;

    float3 col = getPattern(zoomedUV, t);

    float vignette = smoothstep(1.5, 0.3, r);
    float3 finalColor = col; // * vignette;

    return float4(finalColor, 1.0);
}"}

