// HLSL互換のレイ強度計算関数
float rayStrength(float2 raySource, float2 rayRefDirection, float2 coord, float seedA, float seedB, float speed)
{
    float2 sourceToCoord = coord - raySource;
    float cosAngle = dot(normalize(sourceToCoord), rayRefDirection);
    
    return clamp(
        (0.45 + 0.15 * sin(cosAngle * seedA + _Time.x * speed)) +
        (0.3 + 0.2 * cos(-cosAngle * seedB + _Time.x * speed)),
        0.0, 1.0) *
        clamp((_Resolution.x - length(sourceToCoord)) / _Resolution.x, 0.5, 1.0);
}

// ピクセルシェーダー
float4 Frag(VsOutput input) : SV_TARGET
{
    // fragCoord（画面絶対座標）を復元
    float2 fragCoord = input.uv * _Resolution.xy;
    
    // UVy反転処理とY軸反転座標の算出
    float2 uv = fragCoord.xy / _Resolution.xy;
    uv.y = 1.0 - uv.y;
    float2 coord = float2(fragCoord.x, _Resolution.y - fragCoord.y);
    
    // 太陽光線のパラメータ設定
    float2 rayPos1 = float2(_Resolution.x * 0.7, _Resolution.y * -0.4);
    float2 rayRefDir1 = normalize(float2(1.0, -0.116));
    float raySeedA1 = 36.2214;
    float raySeedB1 = 21.11349;
    float raySpeed1 = 1.5;
    
    float2 rayPos2 = float2(_Resolution.x * 0.8, _Resolution.y * -0.6);
    float2 rayRefDir2 = normalize(float2(1.0, 0.241));
    const float raySeedA2 = 22.39910;
    const float raySeedB2 = 18.0234;
    const float raySpeed2 = 1.1;
    
    // 光線のカラー計算
    float4 rays1 =
        float4(1.0, 1.0, 1.0, 1.0) *
        rayStrength(rayPos1, rayRefDir1, coord, raySeedA1, raySeedB1, raySpeed1);
    
    float4 rays2 =
        float4(1.0, 1.0, 1.0, 1.0) *
        rayStrength(rayPos2, rayRefDir2, coord, raySeedA2, raySeedB2, raySpeed2);
    
    float4 rayColor = rays1 * 0.5 + rays2 * 0.4;
    
