#define tau 6.28318530718

static const float ZOOM = 1.0;
static const float SPEED = 0.15;
static const float BRIGHTNESS = 10.0;
static const float CONTRAST = 4.5;

static const float FBM_AMP = 0.49;
static const float FBM_GAIN = 0.72;
static const float FBM_LACUNARITY = 2.1;
static const float CURL_STRENGTH = 4.0;

#define OCTAVES 6

float random(in float2 st) {
    return frac(sin(dot(st.xy, float2(13.9898, 78.233))) * 43758.5453123);
}

float noise(in float2 st) {
    float2 i = floor(st);
    float2 f = frac(st);

    float a = random(i);
    float b = random(i + float2(1.0, 0.0));
    float c = random(i + float2(0.0, 1.0));
    float d = random(i + float2(1.0, 1.0));

    float2 u = f * f * (3.0 - 2.0 * f);

    return lerp(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(in float2 st) {
    float value = 0.0;
    float amplitude = FBM_AMP;
    float2 shift = float2(100.0, 100.0);
    
    // HLSLでの 2x2 行列定義
    float2x2 rot = float2x2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));

    for (int octave = 0; octave < OCTAVES; octave++) {
        value += amplitude * noise(st);
        st = mul(rot, st) * _UserVector0.xy + shift;
        amplitude *= FBM_GAIN;
    }

    return value;
}

