    st.x *= _Resolution.x / _Resolution.y;
    st *= ZOOM * _UserFloat.x;

    float t = _UserFloat.w;

    float2 q = float2(0.0, 0.0);
    q.x = fbm(st + 0.05 * t);
    q.y = fbm(st + float2(1.0, 1.0));
    
    float2 r = float2(0.0, 0.0);
    r.x = fbm(st + CURL_STRENGTH * q + float2(1.7, 9.2) + 0.15 * t);
    r.y = fbm(st + CURL_STRENGTH * q + float2(8.3, 2.8) + 0.126 * t);

