float DrawGrid(float2 uv, float gridDensity, float lineWidth)
{
    // UVをスケールしてグリッドの繰り返しを作る
    float2 gridUV = frac(uv * gridDensity);

    // 0.5を中心に配置し、絶対値をとる
    float2 dist = abs(gridUV - 0.5);

    // スクリーンスペースの偏微分を使用してアンチエイリアス幅を計算
    float2 ddx_uv = ddx(uv * gridDensity);
    float2 ddy_uv = ddy(uv * gridDensity);
    float2 filterWidth = sqrt(ddx_uv * ddx_uv + ddy_uv * ddy_uv);

    // 線幅とぼかしを考慮したステップ処理
    float2 lineVal = smoothstep(0.5 - lineWidth - filterWidth, 0.5 - lineWidth, dist);

    // X軸とY軸の線を結合
    return max(lineVal.x, lineVal.y);
}

float4 Frag(VsOutput input) : SV_TARGET
{
    float d = (0.5 - length(input.uv - 0.5)) * 2.;
    float pulse = pow(1.0 - saturate(_Beat.x), 3.0) + 0.7;
    return DrawGrid(input.uv, 20, 0.010) * d * pulse;
}"}

