float2 Rotate(float2 p, float angle)
{
    float c = cos(angle);
    float s = sin(angle);

    return float2(
        c * p.x - s * p.y,
        s * p.x + c * p.y
    );
}

float3 Mod(float3 x, float y)
{
    return x - y * floor(x / y);
}

float SdOctahedron(float3 p, float s)
{
    p = abs(p);
    return (p.x + p.y + p.z - s) * 0.57735027;
}

float SdBox(float3 p, float3 b)
{
    float3 q = abs(p) - b;

    return length(max(q, 0.0))
        + min(max(q.x, max(q.y, q.z)), 0.0);
}

float MainDist(float3 p, float time, float loopIndex)
{
    p.xy = Rotate(p.xy, p.z * 0.3);
    p.z += time;

    float3 grid = Mod(p, 2.0) - 1.0;

    time += p.z * 0.025;

    float t =
        _Beat.x * 0.5
        + pow(frac(_Beat.x * 0.5), 0.8);

    float octa = SdOctahedron(
        grid,
        sin(time * 0.1 + loopIndex * 0.5) + 1.5
    );

    float sphere =
        length(grid)
        - 0.5 * (1.0 - fmod(t, 1.0));

    float octaSphere = min(octa, sphere);

    return min(
        min(
            min(
                octaSphere,
                SdBox(grid, float3(0.01, 0.01, 1.0))
            ),
            SdBox(grid, float3(1.0, 0.01, 0.01))
        ),
        SdBox(grid, float3(0.01, 1.0, 0.01))
    );
}

float4 Frag(VsOutput input) : SV_TARGET
{
    float time = _Time.x;

    /*
     * Quadはローカル座標で
     * X: -0.5 ～ 0.5
     * Y: -0.5 ～ 0.5
     *
     * なのでUVからQuad上のローカル位置を復元する。
     */
    float3 quadPositionLS = float3(
        input.uv.x - 0.5,
        input.uv.y - 0.5,
        0.0
    );

    /*
     * Quad上のピクセル位置をUnityワールド座標へ変換。
     *
     * QuadのPosition、Rotation、Scale、Sizeが
     * すべてここに反映される。
     */
    float3 pixelPositionWS = mul(
        _QuadLocalToWorld,
        float4(quadPositionLS, 1.0)
    ).xyz;

    /*
     * CameraStageローカル座標を
     * レイマーチングのワールド空間として使用する。
