    float3 cameraPositionRS = mul(
        _QuadWorldToLocal,
        _CameraPositionWS
    ).xyz;

    float3 pixelPositionRS = mul(
        _QuadWorldToLocal,
        float4(pixelPositionWS, 1.0)
    ).xyz;

    /*
     * Unityカメラから、実際のQuad上のピクセルへ向かうRay。
     *
     * これによりUnityカメラの位置・回転・FOVに追従する。
     */
    float3 rayOrigin = cameraPositionRS;

    float3 rayDirection = normalize(
        pixelPositionRS - cameraPositionRS
    );

    float3 col = 0.0;
    float sum = 0.0;
    float3 currentPosition = rayOrigin;

    [loop]
