    col *= float3(0.8, 0.9, 1.1);

    float3 backgroundColor = lerp(
        _BackgroundColor2.rgb,
        _BackgroundColor1.rgb,
        input.uv.y
    );

    float3 finalColor =
        backgroundColor + col;

    return float4(finalColor, 1.0);
}"}

