#define PI 3.14159265359

float4 plas(float2 v, float time)
{
    float c = 0.5 + sin(v.x * 10.0) + cos(sin(time + v.y) * 20.0);
    return float4(sin(c * 0.2 + cos(time)), c * 0.15, cos(c * 0.1 + time / 0.4) * 0.25, 1.0);
}

float rand(float n) { return frac(sin(n) * 43758.5453123); } 
float mod289(float x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
float4 mod289(float4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
float4 perm(float4 x) { return mod289(((x * 34.0) + 1.0) * x); }

float noise(float3 p) {
    float3 a = floor(p);
    float3 d = p - a;
    d = d * d * (3.0 - 2.0 * d);
    float4 b = a.xxyy + float4(0.0, 1.0, 0.0, 1.0);
    float4 k1 = perm(b.xyxy);
    float4 k2 = perm(k1.xyxy + b.zzww);
    float4 c = k2 + a.zzzz;
    float4 k3 = perm(c);
    float4 k4 = perm(c + 1.0);
    float4 o1 = frac(k3 * (1.0 / 41.0));
    float4 o2 = frac(k4 * (1.0 / 41.0));
    float4 o3 = o2 * d.z + o1 * (1.0 - d.z);
    float2 o4 = o3.yw * d.x + o3.xz * (1.0 - d.x);
    return o4.y * d.y + o4.x * (1.0 - d.y);
}

float3 rgb2hsv(float3 c)
{
    float4 K = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    float4 p = lerp(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
    float4 q = lerp(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return float3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

float3 hsv2rgb(float3 c)
{
    float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    float3 p = abs(frac(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * lerp(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

uint pcg(uint v) {
    uint state = v * uint(747796405) + uint(2891336453);
    uint word = ((state >> ((state >> uint(28)) + uint(4))) ^ state) * uint(277803737);
    return (word >> uint(22)) ^ word;
}

float prng(float p) {
    return float(pcg(uint(p))) / float(uint(0xffffffff));
}

float sin01(float v) { return sin(v) * 0.5 + 0.5; }
float noise01(float v) { return noise(float3(v, v, v)) * 0.5 + 0.5; }

float Wave(float rp, float2 rPolarPos, float time)
{
    return cos((0.65 + rp + 0.01 * pow(noise(float3(rPolarPos.x, rPolarPos.y * 30.0, time)) * 2.0, 2.0)) * PI * 2.0);
}

float3 GetCol(float2 uv, float time)
{
    float3 col = float3(uv, 0.0);
    float angle = atan2(uv.y, uv.x);
    float r = length(uv);
    float2 polar = float2(log(r) * 0.4 - time * 0.2, angle);
    float id = floor(polar.x);
    float2 rPolar = float2(frac(polar.x), polar.y + sin(time * rand(id * 5.0) + rand(id) * PI));
    float rp = rPolar.x;
    float2 rPolarPos = float2(cos(rPolar.y), sin(rPolar.y));

    col.xy = rPolar;
    col.z = rand(id);

    col = 0.9 - float3(Wave(rp, rPolarPos, time * 0.1), Wave(rp, rPolarPos, time * 0.1 + 1.25), Wave(rp, rPolarPos, time * 0.1 + 100.5)) * float3(rand(id), rand(id + 10.0), frac(id * 0.5 + 20.0));
    
    float bt = pow(noise01(time * 10.0 + rand(id * 100.0)), 50.0);
    float mask = smoothstep(rp, rp + 0.05, (0.8 - abs(sin(rPolar.y)) * (0.15 + rand(id) * 0.2 + 0.95 * bt)));
    col = col * mask;
    col += (float3)smoothstep(0.9 + noise(float3(rPolarPos.x, rPolarPos.y, 0.1) * 0.05), 1.0, rp);
    
    return col;
}

// ピクセルシェーダー
float4 Frag(VsOutput input) : SV_TARGET
{
    float t = _Time.x;
    float bt = floor(t);

    // 画面絶対座標の復元とアスペクト補正
    float2 fragCoord = input.uv * _Resolution.xy;
    float2 uv = fragCoord.xy / _Resolution.xy;
    uv -= 0.5;
    uv /= float2(_Resolution.y / _Resolution.x, 1.0);

    uv += float2(prng(uv.x + bt), prng(uv.y + 50.0 + bt)) * 0.001;
    uv += float2(cos(t), sin(t * 0.5)) * 0.05;
    uv = sign(uv) * pow(abs(uv), (float2)0.97);
    
    float l = pow(length(uv), 5.0);
    float2 shift = uv * l * 0.1;
    shift = shift + float2(prng(uv.x + t), prng(uv.y + 50.0 + t)) * l * l * 1.0;

    float3 col = float3(0.0, 0.0, 0.0);
    col.r = GetCol(uv - shift, t + 0.1).r;
    col.g = GetCol(uv, t).g;
    col.b = GetCol(uv + shift, t - 0.1).b;
    
    col = noise(float3(t * 10.0, t * 10.0, t * 10.0)) > 0.3 ? col : (float3(1.0, 1.0, 1.0) - col);

    float3 fgColor = col * col * col;

    // --- Background Color の適用 ---
    float3 bgColor = lerp(_BackgroundColor2.rgb, _BackgroundColor1.rgb, input.uv.y);

    // 前景色と背景色を加算合成
    float3 finalColor = bgColor + fgColor;

    return float4(finalColor, 1.0);
